function updateBag(){const n=bag.reduce((a,x)=>a+x.qty,0);$('count').textContent=n>99?'99+':String(n);$('count').hidden=n===0;$('bagBtn').setAttribute('aria-label',`Abrir sacola, ${n} ${n===1?'item':'itens'}`);try{localStorage.setItem(storage,JSON.stringify(bag))}catch{}}
function insert(p,c,s){const existing=bag.find(x=>x.p===p&&x.c===c&&x.s===s);if(existing)existing.qty=Math.min(99,existing.qty+1);else bag.push({p,c,s,qty:1});updateBag()}
let orderName='',orderDelivery='delivery',orderCep='';
const addressKeys=['street','number','complement','district','city','uf'];
let orderAddress=Object.fromEntries(addressKeys.map(k=>[k,'']));
let addressLookup=null, addressStatus='', addressState='';
function setAddressStatus(text,state=''){addressStatus=text;addressState=state;const el=$('cepStatus');if(el){el.textContent=text;el.dataset.state=state}}
async function lookupCep(f){const cep=f.elements.cep.value.replace(/\D/g,'');if(cep.length!==8){setAddressStatus('Informe um CEP de 8 dígitos.','warning');return}addressLookup?.abort();const ctrl=new AbortController();addressLookup=ctrl;const timeout=setTimeout(()=>ctrl.abort(),7000);setAddressStatus('Consultando cidade e UF…','loading');$('lookupCep').disabled=true;try{const resp=await fetch('https://viacep.com.br/ws/'+cep+'/json/',{signal:ctrl.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!resp.ok)throw Error();const data=await resp.json();if(addressLookup!==ctrl||!f.isConnected||f.elements.cep.value.replace(/\D/g,'')!==cep)return;if(data.erro){setAddressStatus('CEP não localizado. Confira os dígitos.','warning');return}orderAddress.city=String(data.localidade||'');orderAddress.uf=String(data.uf||'');setAddressStatus([orderAddress.city,orderAddress.uf].filter(Boolean).join(' — ')||'CEP localizado.','success')}catch{if(addressLookup===ctrl&&f.isConnected)setAddressStatus('Consulta indisponível. Você ainda pode enviar seu CEP à loja.','warning')}finally{clearTimeout(timeout);if(addressLookup===ctrl){addressLookup=null;if(f.isConnected)$('lookupCep').disabled=false}}}
function showBag(restore){const previousScroll=panel.scrollTop;updateBag();if(!bag.length){openPanel('Sua sacola',`<div class="empty">${icon('bag')}<h3>Sua sacola está vazia.</h3><p class="note">Descubra as peças da coleção APELL.</p><button class="primary wide" id="continue">Explorar coleção ${icon('arrow')}</button>${lastBag.length?'<button id="restoreBag" class="outline wide">Recuperar última sacola</button>':''}</div>`);if($('restoreBag'))$('restoreBag').onclick=()=>{restoreBag();showBag()};$('continue').onclick=()=>{panel.close();goCollection()};return}openPanel('Sua sacola',`<div class="bag-intro"><span>${bag.reduce((n,x)=>n+x.qty,0)} peça(s) escolhida(s)</span><span>01 / 03</span></div>`);bag.forEach((x,index)=>{const p=itemProduct(x),color=p.colors[x.c],el=document.createElement('div');el.className='cart-item';el.innerHTML=`<img src="${x.p===2?'img/'+color[1]+'.webp':image(color)}" alt="${x.p===2?'Recorte da campanha: ':''}${p.title} em ${color[0]}"><div><strong>${p.title}</strong><small>${color[0]}${x.p===2?' · Medidas a confirmar':' · Tamanho '+x.s}</small><div class="row"><div class="stepper"><button data-step="minus" aria-label="Diminuir quantidade de ${p.title} ${color[0]}" ${x.qty===1?'disabled':''}>${icon('minus')}</button><span>${x.qty}</span><button data-step="plus" aria-label="Aumentar quantidade de ${p.title} ${color[0]}" ${x.qty===99?'disabled':''}>${icon('plus')}</button></div><b>${itemPrice(x)}</b></div><div class="row"><button class="link" aria-label="Remover ${p.title} ${color[0]}">Remover</button></div></div>`;const [minus,plus,remove]=el.querySelectorAll('button');minus.onclick=()=>{x.qty--;showBag([index,'minus'])};plus.onclick=()=>{x.qty++;showBag([index,'plus'])};remove.onclick=()=>{bag.splice(index,1);showBag([Math.max(0,index-1),'plus'])};body.append(el)});const summary=document.createElement('div');summary.className='bag-summary';summary.innerHTML=`<div class="total"><strong>Subtotal</strong><strong>${sumLabel()}</strong></div><p class="note">${hasConsult()?'Os valores dos bonés serão confirmados pela loja. ':''}Frete e disponibilidade a confirmar.</p><button class="primary wide" id="startCheckout">Continuar para o pedido ${icon('arrow')}</button><button id="continue" class="outline wide">Continuar escolhendo</button><button class="link clear-bag" id="emptyBag">Esvaziar sacola</button>`;body.append(summary);if(Array.isArray(restore)){panel.scrollTop=previousScroll;const item=body.querySelectorAll('.cart-item')[restore[0]];(item?.querySelector(`[data-step="${restore[1]}"]:not(:disabled)`)||item?.querySelector('button:not(:disabled)')||$('continue'))?.focus({preventScroll:true})}$('emptyBag').onclick=()=>{if(confirm('Esvaziar a sacola? Você poderá recuperar os itens por até 7 dias.')){clearBag();resetCustomer();showBag()}};$('continue').onclick=()=>panel.close();$('startCheckout').onclick=()=>{panel.close();location.hash='checkout'}}
