function syncFavorites(){document.querySelectorAll('[data-fav]').forEach(b=>{const on=favorites.has(b.dataset.fav);b.setAttribute('aria-pressed',String(on));b.setAttribute('title',on?'Remover dos favoritos':'Salvar nos favoritos')});$('favCount').hidden=!favorites.size;$('favCount').textContent=favorites.size;$('favoriteBtn').setAttribute('aria-label',`Favoritos, ${favorites.size} peças`);try{localStorage.setItem('apell.favorites.v1',JSON.stringify([...favorites]))}catch{}}
