function activateView(html,title){if(addressLookup){addressLookup.abort();addressLookup=null;}$('motionToast').hidden=true;home.hidden=true;footer.hidden=true;view.hidden=false;$('skipContent').href='#motionView';document.querySelectorAll('.desktop-nav a').forEach(a=>{a.classList.remove('active');a.removeAttribute('aria-current')});view.innerHTML=html;document.title=title+' | APELL';resetPageMeta(document.title);window.scrollTo({top:0,behavior:'instant'});view.focus({preventScroll:true});if(!reduced())view.animate([{opacity:.85},{opacity:1}],{duration:180,easing:'ease-out'})}
