function renderCheckout(){if(!bag.length){activateView(`<div class="checkout-empty"><a href="#colecao">${icon('left')} Voltar à coleção</a><h1>Sua sacola está vazia.</h1><a class="primary" href="#colecao">Escolher peças ${icon('arrow')}</a></div>`,'Sacola vazia');return}activateView(`<div class="motion-crumb"><a href="#colecao">${icon('left')} Continuar comprando</a><button class="link crumb-end" id="editBag">${icon('bag')} Editar sacola</button></div><div class="checkout-layout"><section class="checkout-form"><span class="stage-category">Seu pedido APELL</span><h1>Solicitar compra</h1><p class="checkout-lead">Confira sua sacola, informe como deseja receber e envie a solicitação à APELL pelo WhatsApp.</p><form id="checkoutForm"><label for="orderName">Seu nome</label><input id="orderName" name="nome" required maxlength="80" autocomplete="name" placeholder="Como podemos chamar você?"><fieldset><legend>Como deseja receber?</legend><label class="delivery-choice"><input type="radio" name="delivery" value="delivery"><span><strong>Entrega</strong><small>Consultar frete com a loja</small></span>${icon('truck')}</label><label class="delivery-choice"><input type="radio" name="delivery" value="pickup"><span><strong>Consultar retirada</strong><small>Verificar possibilidade com a APELL</small></span>${icon('bag')}</label></fieldset><div id="cepField"><label for="orderCep">CEP para cotação de frete</label><div class="cep-row"><input id="orderCep" name="cep" placeholder="00000-000" inputmode="numeric" autocomplete="postal-code" maxlength="9" pattern="[0-9]{5}-?[0-9]{3}" aria-describedby="cepStatus"><button type="button" id="lookupCep" class="outline">Consultar CEP</button></div><p id="cepStatus" class="cep-status" role="status" aria-live="polite"></p><small class="note">Consultar cidade e UF é opcional. O endereço completo será combinado com a loja.</small></div><p class="note">${whatsappReady?'Não solicitamos endereço completo nem pagamento nesta etapa.':'Modo demonstração: use dados fictícios. Nenhum pedido é enviado.'}</p><button class="link privacy-trigger" data-privacy type="button">Como seus dados são utilizados</button><button class="primary wide" type="submit">${whatsappReady?'Solicitar pelo WhatsApp':'Preparar solicitação'} ${icon('chat')}</button><p class="note">Nenhuma compra é confirmada neste site. A sacola permanece salva até você decidir esvaziá-la.</p><div id="requestStatus" role="status" class="request-status" hidden></div><a id="requestFallback" class="outline wide" target="_blank" rel="noopener noreferrer" hidden>Abrir WhatsApp novamente ${icon('up')}</a><details class="request-options"><summary>Outras opções</summary><button type="button" class="outline wide" id="copyRequest">Copiar solicitação</button><button type="button" class="outline wide" id="downloadRequest">Baixar resumo em PDF</button><button type="button" class="link" id="finishRequest" hidden>Já enviei — esvaziar sacola</button></details></form></section><aside class="checkout-summary" id="checkoutSummary"><div class="summary-head"><h2>Sua sacola</h2><span>${bag.reduce((n,x)=>n+x.qty,0)} peça(s)</span></div>${orderItems()}<div class="checkout-totals"><div><span>Subtotal</span><b>${sumLabel()}</b></div><div><span>Frete</span><span>A confirmar</span></div><div class="summary-total"><span>Total parcial</span><strong>${sumLabel()}</strong></div></div><p class="note" id="consultNote">${hasConsult()?'Bonés: valor sob consulta e não incluído no subtotal conhecido. ':''}Preço final, estoque, pagamento e entrega serão confirmados pela APELL.</p><a class="checkout-help" href="https://wa.me/${whatsappNumber}?text=Oi%2C%20APELL!%20Preciso%20de%20ajuda%20com%20meu%20pedido." target="_blank" rel="noopener noreferrer">${icon('chat')} Precisa de ajuda com o pedido?</a></aside></div>`,'Finalizar pedido');$('editBag').onclick=()=>showBag();const f=$('checkoutForm');f.elements.nome.value=orderName;f.elements.delivery.value=orderDelivery;f.elements.cep.value=orderCep;setAddressStatus(addressState==='loading'?'':addressStatus,addressState==='loading'?'':addressState);
const sync=()=>{orderDelivery=f.elements.delivery.value;const active=orderDelivery==='delivery';$('cepField').hidden=!active;f.elements.cep.disabled=!active;f.elements.cep.required=active;$('lookupCep').disabled=!active||!!addressLookup;if(!active&&addressLookup){addressLookup.abort();addressLookup=null;setAddressStatus('')}};
f.elements.nome.oninput=()=>{orderName=f.elements.nome.value;f.elements.nome.setCustomValidity('')};
f.addEventListener('change',sync);
f.elements.cep.oninput=()=>{const v=f.elements.cep.value.replace(/\D/g,'').slice(0,8),formatted=v.length>5?v.slice(0,5)+'-'+v.slice(5):v;if(formatted!==orderCep){addressLookup?.abort();addressLookup=null;orderAddress.city='';orderAddress.uf='';setAddressStatus('')};f.elements.cep.value=formatted;orderCep=formatted;sync()};
$('lookupCep').onclick=()=>{if(f.elements.cep.reportValidity())lookupCep(f)};
let sentRef='';
const invalidate=()=>{sentRef='';$('requestFallback').hidden=true;$('requestFallback').removeAttribute('href');$('finishRequest').hidden=true;$('requestStatus').hidden=true};
f.addEventListener('input',invalidate);f.addEventListener('change',invalidate);
const status=(msg)=>{const el=$('requestStatus');el.hidden=false;el.textContent=msg};
const prepare=()=>{orderName=f.elements.nome.value.trim();orderCep=f.elements.cep.value;orderDelivery=f.elements.delivery.value;if(!orderName){f.elements.nome.setCustomValidity('Informe seu nome.');f.elements.nome.reportValidity();return null}if(!f.reportValidity())return null;if(!bag.length){status('Sua sacola está vazia.');return null}addressLookup?.abort();addressLookup=null;setAddressStatus(addressState==='loading'?'':addressStatus,addressState==='loading'?'':addressState);sync();const ref=orderReference();return {ref,message:requestMessage(ref,orderName,bag,orderDelivery,orderCep,orderAddress)}};
f.onsubmit=e=>{e.preventDefault();const req=prepare();if(!req)return;if(!whatsappReady){status('WhatsApp indisponível. Use as opções para copiar ou baixar a solicitação.');return}const url='https://wa.me/'+whatsappNumber+'?text='+encodeURIComponent(req.message);const link=$('requestFallback');link.href=url;link.hidden=false;sentRef=req.ref;$('finishRequest').hidden=false;status('Confira a mensagem no WhatsApp e envie quando estiver pronto. Sua sacola continua salva. Se não abrir, use o link abaixo.');link.click()};
$('copyRequest').onclick=async()=>{const req=prepare();if(!req)return;try{await navigator.clipboard.writeText(req.message);status('Solicitação copiada.')}catch{const area=document.createElement('textarea');area.value=req.message;area.readOnly=true;area.setAttribute('aria-label','Solicitação para copiar');$('requestStatus').replaceChildren(area);$('requestStatus').hidden=false;area.focus();area.select()}};
$('downloadRequest').onclick=()=>{const req=prepare();if(req)downloadSummary(req.ref,req.message)};
$('finishRequest').onclick=()=>{if(!sentRef||orderReference()!==sentRef){invalidate();status('A solicitação mudou. Envie a versão atual antes de esvaziar a sacola.');return}if(!confirm('Você já enviou a mensagem à APELL? Esvaziar a sacola agora?'))return;lastResult={ref:sentRef,count:bag.reduce((n,x)=>n+x.qty,0),total:sumLabel()};clearBag(sentRef);resetCustomer();location.hash='finalizado'};
sync()}
function requestMessage(ref,name,items,delivery,cep,address){return 'Oi, APELL! Aqui é '+name+'.\nReferência: '+ref+'\n\n'+items.map(x=>x.qty+' × '+itemProduct(x).title+' · '+itemProduct(x).colors[x.c][0]+(x.p===2?'':' · '+x.s)+' — '+itemPrice(x)).join('\n')+'\n\nSubtotal: '+sumLabel()+'\n'+(delivery==='delivery'?['Consulta de entrega:',[address.city,address.uf].filter(Boolean).join(' - '),'CEP: '+cep].filter(Boolean).join('\n'):'Gostaria de consultar retirada.')+'\nPodem confirmar disponibilidade, frete e pagamento?'}
function renderFinished(){if(!lastResult){location.replace('#colecao');return}const {ref,count,total}=lastResult;activateView(`<div class="finish-page"><span class="ready-mark">${icon('check')}</span><span class="stage-category">Sua próxima escolha começa aqui</span><h1>Solicitação encaminhada</h1><p>Você informou que enviou a solicitação pelo WhatsApp. Sua sacola foi esvaziada.</p><div class="order-reference"><small>Referência da solicitação</small><strong>${ref}</strong><span>${count} peça(s) · ${total}</span></div><p class="note">O atendimento da APELL ainda precisa confirmar estoque, frete e pagamento.</p><a href="#colecao" class="primary wide">Voltar à coleção ${icon('arrow')}</a>${lastBag.length?'<button class="outline wide" id="recoverFinished">Recuperar sacola</button>':''}</div>`,'Solicitação encaminhada');if($('recoverFinished'))$('recoverFinished').onclick=()=>{restoreBag();location.hash='checkout'}}
// Self-contained PDF: WinAnsi Helvetica, text only, automatic page breaks. No customer data is uploaded.
function downloadSummary(ref,message){
 const lines=[];for(const paragraph of message.split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(word.length>74){if(line){lines.push(line);line=''}for(let i=0;i<word.length;i+=70)lines.push(word.slice(i,i+70));continue}if((line+' '+word).length>74){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line)}
 lines.push('','Solicitação, não é comprovante de compra ou pagamento.','Estoque, frete e pagamento sujeitos à confirmação da APELL.');
 const esc=t=>Array.from(t.replace(/—/g,'-').replace(/·/g,'-')).map(ch=>{const n=ch.charCodeAt(0);return n>255?'?':n<32||n>126?'\\'+n.toString(8).padStart(3,'0'):['(',')','\\'].includes(ch)?'\\'+ch:ch}).join('');
 const objs=['',''];const add=o=>{objs.push(o);return objs.length};const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');const kids=[];
 for(let i=0;i<lines.length;i+=38){const part=lines.slice(i,i+38);let stream='0.35 0.15 0.16 rg\nBT /F1 25 Tf 48 786 Td (APELL) Tj ET\nBT /F1 13 Tf 48 752 Td (Resumo da solicitacao) Tj ET\n0.15 0.12 0.12 rg\nBT /F1 11 Tf 48 715 Td 16 TL\n'+part.map((l,n)=>(n?'T* ':'')+'('+esc(l)+') Tj').join('\n')+'\nET';const content=add('<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream');kids.push(add('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 '+font+' 0 R >> >> /Contents '+content+' 0 R >>'))}
 objs[0]='<< /Type /Catalog /Pages 2 0 R >>';objs[1]='<< /Type /Pages /Kids ['+kids.map(n=>n+' 0 R').join(' ')+'] /Count '+kids.length+' >>';let pdf='%PDF-1.4\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const xref=pdf.length;pdf+='xref\n0 '+offsets.length+'\n0000000000 65535 f \n'+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+offsets.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download='APELL-'+ref+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)
}
function route(){const [r,a,b]=(location.hash.slice(1)||document.body.dataset.productRoute||'').split('/');
 if(r==='produto'&&a==='bones'){const i=caps.findIndex(x=>slug(x.name)===b);if(i>=0){renderCapPage(i);return}}
 if(r==='produto'){const p=products.findIndex(x=>x.route===a),c=products[p]?.colors.findIndex(x=>slug(x[0])===b);if(p>=0&&c>=0){renderProductPage(p,c);return}}
 if(r==='checkout'){renderCheckout();return}if(r==='pedido'){history.replaceState(null,'','#checkout');renderCheckout();return}if(r==='finalizado'){renderFinished();return}
 if(['conjuntos','camisetas','bones'].includes(r)){const p=['conjuntos','camisetas','bones'].indexOf(r);showHome(false);selectFilter(String(p),true);if(a&&p<2){const c=products[p].colors.findIndex(x=>slug(x[0])===a);if(c>=0){showProduct(p,c);return}}requestAnimationFrame(()=>$('colecao').scrollIntoView({behavior:reduced()?'instant':'smooth'}));return}
 if(r==='inicio'||!r){showHome();selectFilter('all');return}
 if(r==='colecao'){showHome(false);selectFilter('all');requestAnimationFrame(()=>$('colecao').scrollIntoView({behavior:reduced()?'instant':'smooth'}));return}
 showHome();
}
